package com.example.hiringsys.entity; import com.example.hiringsys.enums.TipoRede; import jakarta.persistence.*;
@Entity @Table(name="rede") public class Rede { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=255) private String url; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private TipoRede tipo; public Long getId(){return id;} public void setId(Long v){id=v;} public String getUrl(){return url;} public void setUrl(String v){url=v;} public TipoRede getTipo(){return tipo;} public void setTipo(TipoRede v){tipo=v;} }
